     1→#!/usr/bin/env node
     2→
     3→/**
     4→ * FreeLang Nexus CLI
     5→ * Usage:
     6→ *   nexus run <file>      - 파일 실행
     7→ *   nexus compile <file>  - 코드 생성만 (컴파일/실행 안함)
     8→ *   nexus check <file>    - 문법 검사만
     9→ *   nexus repl            - 대화형 셸
    10→ */
    11→
    12→import * as fs from 'fs';
    13→import * as path from 'path';
    14→import NexusLexer from './lexer/nexus-lexer';
    15→import { NexusParser } from './parser/nexus-parser';
    16→import { NexusCodegen } from './codegen/nexus-codegen';
    17→import { NexusRunner } from './runtime/nexus-runner';
    18→import { NexusRepl } from './repl/nexus-repl';
    19→
    20→function printUsage() {
    21→  console.log(`
    22→FreeLang Nexus CLI
    23→
    24→Usage:
    25→  nexus run <file>      실행: .fl 파일 실행
    26→  nexus compile <file>  컴파일: C/Python 코드만 출력
    27→  nexus check <file>    검사: 문법 검사만
    28→  nexus repl            대화형 셸
    29→  nexus --version       버전 표시
    30→  nexus --help          도움말
    31→
    32→Examples:
    33→  nexus run hello.fl
    34→  nexus compile hello.fl
    35→  nexus check hello.fl
    36→  nexus repl
    37→`);
    38→}
    39→
    40→async function runFile(filePath: string): Promise<void> {
    41→  try {
    42→    // 파일 읽기
    43→    if (!fs.existsSync(filePath)) {
    44→      console.error(`❌ 파일을 찾을 수 없음: ${filePath}`);
    45→      process.exit(1);
    46→    }
    47→
    48→    const source = fs.readFileSync(filePath, 'utf-8');
    49→
    50→    // Lexer
    51→    const lexer = new NexusLexer(source);
    52→    const tokens = lexer.tokenize();
    53→
    54→    // Parser
    55→    const parser = new NexusParser(tokens);
    56→    const ast = parser.parse();
    57→
    58→    // CodeGen
    59→    const codegen = new NexusCodegen();
    60→    const result = codegen.generateProgram(ast);
    61→
    62→    // Runner
    63→    const runner = new NexusRunner();
    64→    const runResult = runner.run(result);
    65→
    66→    // 결과 출력
    67→    if (runResult.cOutput) {
    68→      console.log(runResult.cOutput);
    69→    }
    70→    if (runResult.pythonOutput) {
    71→      console.log(runResult.pythonOutput);
    72→    }
    73→
    74→    // 에러 출력
    75→    if (runResult.errors.length > 0) {
    76→      console.error('❌ 에러:');
    77→      runResult.errors.forEach((e) => console.error(`  ${e}`));
    78→      process.exit(1);
    79→    }
    80→  } catch (e) {
    81→    console.error(`❌ 오류: ${(e as Error).message}`);
    82→    process.exit(1);
    83→  }
    84→}
    85→
    86→async function compileFile(filePath: string): Promise<void> {
    87→  try {
    88→    if (!fs.existsSync(filePath)) {
    89→      console.error(`❌ 파일을 찾을 수 없음: ${filePath}`);
    90→      process.exit(1);
    91→    }
    92→
    93→    const source = fs.readFileSync(filePath, 'utf-8');
    94→
    95→    // Lexer
    96→    const lexer = new NexusLexer(source);
    97→    const tokens = lexer.tokenize();
    98→
    99→    // Parser
   100→    const parser = new NexusParser(tokens);
   101→    const ast = parser.parse();
   102→
   103→    // CodeGen
   104→    const codegen = new NexusCodegen();
   105→    const result = codegen.generateProgram(ast);
   106→
   107→    // C 코드 출력
   108→    if (result.c) {
   109→      console.log('/* === C Code ===*/');
   110→      console.log(result.c);
   111→    }
   112→
   113→    // Python 코드 출력
   114→    if (result.python) {
   115→      if (result.c) {
   116→        console.log('\n# === Python Code ===');
   117→      }
   118→      console.log(result.python);
   119→    }
   120→
   121→    if (!result.c && !result.python) {
   122→      console.log('// (No code generated)');
   123→    }
   124→  } catch (e) {
   125→    console.error(`❌ 오류: ${(e as Error).message}`);
   126→    process.exit(1);
   127→  }
   128→}
   129→
   130→async function checkFile(filePath: string): Promise<void> {
   131→  try {
   132→    if (!fs.existsSync(filePath)) {
   133→      console.error(`❌ 파일을 찾을 수 없음: ${filePath}`);
   134→      process.exit(1);
   135→    }
   136→
   137→    const source = fs.readFileSync(filePath, 'utf-8');
   138→
   139→    // Lexer
   140→    const lexer = new NexusLexer(source);
   141→    const tokens = lexer.tokenize();
   142→
   143→    // Parser
   144→    const parser = new NexusParser(tokens);
   145→    const ast = parser.parse();
   146→
   147→    console.log('✅ 문법 검사 통과');
   148→    console.log(`   함수: ${ast.body.filter((b: any) => b.type === 'VFunction' || b.type === 'PyFunction').length}개`);
   149→  } catch (e) {
   150→    console.error(`❌ 오류: ${(e as Error).message}`);
   151→    process.exit(1);
   152→  }
   153→}
   154→
   155→async function main() {
   156→  const args = process.argv.slice(2);
   157→
   158→  if (args.length === 0) {
   159→    printUsage();
   160→    process.exit(0);
   161→  }
   162→
   163→  const cmd = args[0];
   164→  const file = args[1];
   165→
   166→  if (cmd === '--help' || cmd === '-h') {
   167→    printUsage();
   168→  } else if (cmd === '--version' || cmd === '-v') {
   169→    console.log('FreeLang Nexus 1.0.0');
   170→  } else if (cmd === 'run') {
   171→    if (!file) {
   172→      console.error('❌ 파일 경로 필요: nexus run <file>');
   173→      process.exit(1);
   174→    }
   175→    await runFile(file);
   176→  } else if (cmd === 'compile') {
   177→    if (!file) {
   178→      console.error('❌ 파일 경로 필요: nexus compile <file>');
   179→      process.exit(1);
   180→    }
   181→    await compileFile(file);
   182→  } else if (cmd === 'check') {
   183→    if (!file) {
   184→      console.error('❌ 파일 경로 필요: nexus check <file>');
   185→      process.exit(1);
   186→    }
   187→    await checkFile(file);
   188→  } else if (cmd === 'repl') {
   189→    const repl = new NexusRepl();
   190→    repl.start();
   191→  } else {
   192→    console.error(`❌ 알 수 없는 커맨드: ${cmd}`);
   193→    printUsage();
   194→    process.exit(1);
   195→  }
   196→}
   197→
   198→main();
   199→

