    80→  /** export된 함수 이름 목록 */
    81→  exports: string[];
    82→  /** 경고 메시지 (미지원 기능 등) */
    83→  warnings: string[];
    84→  /** 문자열 상수 메모리 맵: string value → {offset, length} */
    85→  stringTable: Map<string, { offset: number; length: number }>;
    86→}
    87→
    88→// ─── 문자열 관련 헬퍼 ────────────────────────────────────────────────────────
    89→
    90→/**
    91→ * 문자열을 WAT data 섹션 이스케이프 형식으로 변환
    92→ * 예: "hello\n" → "hello\n" (WAT에서 \n은 \0a)
    93→ */
    94→function stringToWatData(s: string): string {
    95→  let result = '';
    96→  for (let i = 0; i < s.length; i++) {
    97→    const c = s.charCodeAt(i);
    98→    if (c === 0x0a) result += '\\0a';       // newline
    99→    else if (c === 0x0d) result += '\\0d';  // carriage return
   100→    else if (c === 0x22) result += '\\22';  // double quote
   101→    else if (c === 0x5c) result += '\\5c';  // backslash
   102→    else if (c >= 0x20 && c < 0x7f) result += s[i]; // printable ASCII
   103→    else result += `\\${c.toString(16).padStart(2, '0')}`;
   104→  }
   105→  return result;
   106→}
   107→
   108→/** UTF-8 바이트 길이 계산 (ASCII만 지원, 확장은 향후) */
   109→function utf8ByteLength(s: string): number {
   110→  // For simplicity, count actual bytes including \n etc
   111→  return s.length; // ASCII-only assumption for WAT data
   112→}
   113→
   114→/**
   115→ * 파서가 저장하는 문자열 값(따옴표 포함)에서 실제 내용을 추출합니다.
   116→ * "\"hello\"" → "hello"
   117→ * "hello" (따옴표 없음) → "hello"
   118→ */
   119→function unquoteString(s: string): string {
   120→  if (s.length >= 2 && s.startsWith('"') && s.endsWith('"')) {
   121→    return s.slice(1, -1);
   122→  }
   123→  if (s.length >= 2 && s.startsWith("'") && s.endsWith("'")) {
   124→    return s.slice(1, -1);
   125→  }
   126→  return s;
   127→}
   128→
   129→/**
   130→ * FreeLang V 모드 AST → WAT 코드 생성기
   131→ *
   132→ * 사용 예:
