#### CLI 확장: `nexus build`

`index.ts`에 `build` 서브커맨드 추가:

```typescript
async function buildFile(filePath: string, target: string, outDir: string): Promise<void> {
  const source = fs.readFileSync(filePath, 'utf-8');
  const baseName = path.basename(filePath, '.fl');

  if (target === 'wasm') {
    // 1. WAT 생성
    const runner = new NexusWasmRunner();
    const watResult = runner.generateWat(source);

    // 2. .wat 저장 (디버깅용)
    const watPath = path.join(outDir, `${baseName}.wat`);
    fs.writeFileSync(watPath, watResult.wat);

    // 3. .wasm 바이너리 생성
    const wasm = await runner.watToWasm(watResult.wat);
    const wasmPath = path.join(outDir, `${baseName}.wasm`);
    fs.writeFileSync(wasmPath, Buffer.from(wasm));

    // 4. JS glue 생성
    const jsGlue = generateJsGlue({
      wasmFile: `${baseName}.wasm`,
      exports: watResult.exports,
      moduleName: baseName,
    });
    const jsPath = path.join(outDir, `${baseName}.js`);
    fs.writeFileSync(jsPath, jsGlue);

    console.log(`✅ 빌드 완료:`);
    console.log(`   ${watPath}`);
    console.log(`   ${wasmPath}`);
    console.log(`   ${jsPath}`);
  }
}
```

CLI 파싱 로직: `nexus build [--target=wasm] [--out=./dist] <file>`

